import { expect, sample, test, uniqueName } from "../../fixtures";

const EXPECTED_ACTIONS = ["vendor.created", "document.uploaded", "document.extracted"];

test.describe("vendor audit trail", () => {
  test(
    "audit events are listed oldest first with actor and action",
    { tag: "@AUD-01" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads a W-9 for it
      const member = await apiAs("member");
      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Audit Vendor"),
          category: "services",
          contact_email: "billing@audit-vendor.test",
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4\n% audit trail test W-9\n%%EOF\n"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);

      // Act: request the audit trail. Extraction runs asynchronously, so poll
      // until the expected events have been recorded.
      let auditResponse;
      await expect
        .poll(
          async () => {
            auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
            expect(auditResponse.status()).toBe(200);
            const body = await auditResponse.json();
            return body.items.map((event: { action: string }) => event.action);
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .toEqual(EXPECTED_ACTIONS);

      // Assert
      expect(auditResponse!.status()).toBe(200);
      const trail = await auditResponse!.json();
      expect(trail.items.map((event: { action: string }) => event.action)).toEqual(EXPECTED_ACTIONS);

      for (const event of trail.items) {
        expect(event.actor).toBeTruthy();
        expect(typeof event.actor.id).toBe("string");
        expect(event.actor.id.length).toBeGreaterThan(0);
        expect(typeof event.actor.name).toBe("string");
        expect(event.actor.name.length).toBeGreaterThan(0);
        expect(typeof event.actor.email).toBe("string");
        expect(event.actor.email).toContain("@");

        expect(typeof event.at).toBe("string");
        expect(Number.isNaN(Date.parse(event.at))).toBe(false);
      }

      // Events are oldest first, so timestamps must be non-decreasing.
      const times = trail.items.map((event: { at: string }) => Date.parse(event.at));
      for (let i = 1; i < times.length; i++) {
        expect(times[i]).toBeGreaterThanOrEqual(times[i - 1]);
      }
    },
  );
});
